:root {
  color-scheme: light dark;
  --ink: #1b1b1f;
  --muted: #5b5f66;
  --accent: #0f766e;
  --border: #d9dce1;
  --bg: #fafafa;
  --surface: #ffffff;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
}

#app {
  max-width: 640px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.page-header h1 {
  margin-bottom: 0.1rem;
}

.tagline {
  margin-top: 0;
  color: var(--muted);
}

#note-form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.field label {
  font-weight: 600;
  font-size: 0.9rem;
}

input[type="text"],
input[type="search"],
textarea {
  font: inherit;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  color: var(--ink);
}

textarea {
  resize: vertical;
  font-family: ui-monospace, SFMono-Regular, monospace;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

button[type="submit"] {
  align-self: flex-start;
  font: inherit;
  padding: 0.5rem 1.25rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: white;
  cursor: pointer;
}

button[type="submit"]:hover {
  filter: brightness(1.1);
}

.search-section {
  margin-bottom: 1.5rem;
}

.search-section label {
  display: block;
  font-weight: 600;
  font-size: 0.9rem;
  margin-bottom: 0.25rem;
}

#search {
  width: 100%;
}

#results-line {
  color: var(--muted);
  font-size: 0.9rem;
  min-height: 1.2em;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.85rem 1rem;
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.25rem 0.75rem;
}

.note-avatar {
  grid-row: 1 / span 2;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.note-title {
  margin: 0;
  font-size: 1.05rem;
  cursor: pointer;
  width: fit-content;
}

.note-title:hover,
.note-title:focus-visible {
  color: var(--accent);
  outline: none;
  text-decoration: underline;
}

.note-body {
  margin: 0;
  color: var(--ink);
}

.note[aria-current="true"] {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

*:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

